// Fake `claude` (Claude Code) for Windows CI, started through claude.cmd, an npm shim like the real one.
//
// It accepts the arguments ClaudeCodeProvider passes (-p, --output-format stream-json, --verbose, --permission-mode,
// and in ask mode --mcp-config and --permission-prompt-tool mcp__tristan__approve) and writes stream-json lines ending
// in CR LF. Its one action is "write hello.txt (content hi) in the working folder":
// - with --mcp-config it does what Claude Code does with an MCP server: it starts the configured `command` with its
//   `args` and with the config's `env` block added to its environment, speaks MCP (JSON-RPC over stdio) to it, and
//   calls the `approve` tool before writing. That server is `tristan --mcp-permission <endpoint>`, so the approval
//   travels through the real shim and the loopback transport to the operator.
// - without it, --permission-mode auto, acceptEdits or bypassPermissions allows the write; anything else refuses it.
// A task containing "sleep" leaves a sleeping process tree (see fake-common); "fail" ends with an error result.
'use strict';
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const { EOL, record, option, sleepTree } = require('fake-common');

const argv = process.argv.slice(2);
record('claude', argv);
const out = (object) => process.stdout.write(JSON.stringify(object) + EOL);
const result = (text, isError, code) => {
  out({ type: 'result', subtype: isError ? 'error_during_execution' : 'success', is_error: isError, result: text });
  process.exit(code);
};

const task = option(argv, '-p');
const mode = option(argv, '--permission-mode');
const mcpConfig = option(argv, '--mcp-config');
if (option(argv, '--output-format') !== 'stream-json' || !argv.includes('--verbose') || task === undefined) {
  process.stderr.write('fake claude: expected -p <task> --output-format stream-json --verbose' + EOL);
  process.exit(64);
}

out({ type: 'system', subtype: 'init', session_id: 'fake-session', cwd: process.cwd(), permissionMode: mode });
out({ type: 'assistant', message: { content: [{ type: 'text', text: `Task: ${task}` }] } });

if (/\bsleep\b/.test(task)) {
  sleepTree();
} else if (/\bfail\b/.test(task)) {
  result('fake claude failed on purpose', true, 1);
} else if (!mcpConfig) {
  finish(['auto', 'acceptEdits', 'bypassPermissions'].includes(mode), `permission mode ${mode}`);
} else {
  askThroughMCP();
}

function finish(allowed, why) {
  const target = path.join(process.cwd(), 'hello.txt');
  if (allowed) {
    fs.writeFileSync(target, 'hi');
    out({ type: 'assistant', message: { content: [{ type: 'tool_use', id: 'toolu_1', name: 'Write', input: { file_path: target, content: 'hi' } }] } });
    result('created hello.txt', false, 0);
  } else {
    result(`did not create hello.txt: ${why}`, false, 0);
  }
}

function askThroughMCP() {
  if (option(argv, '--permission-prompt-tool') !== 'mcp__tristan__approve') result('expected --permission-prompt-tool mcp__tristan__approve', true, 65);
  const server = JSON.parse(fs.readFileSync(mcpConfig, 'utf8')).mcpServers.tristan;
  const secrets = Object.values(server.env || {});
  // The approval tokens belong in `env` only, never on a command line (ours or the shim's).
  if (secrets.some((secret) => [...argv, ...server.args].some((arg) => arg.includes(secret)))) result('a token was on a command line', true, 66);
  setTimeout(() => result('no answer from the approval server within 60 s', true, 70), 60000).unref();

  const shim = spawn(server.command, server.args, { env: { ...process.env, ...(server.env || {}) }, stdio: ['pipe', 'pipe', 'inherit'] });
  shim.on('error', (error) => result(`could not start the MCP server: ${error.message}`, true, 67));
  const pending = new Map();
  let buffer = '';
  let nextId = 1;
  shim.stdout.on('data', (data) => {
    buffer += data;
    let end;
    while ((end = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0, end).trim();
      buffer = buffer.slice(end + 1);
      if (!line) continue;
      const message = JSON.parse(line);
      const resolve = pending.get(message.id);
      if (resolve) { pending.delete(message.id); resolve(message); }
    }
  });
  const call = (method, params) => new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, resolve);
    shim.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
  });

  (async () => {
    const init = await call('initialize', { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'fake-claude', version: '0.0.1' } });
    if (!init.result || !init.result.serverInfo) result('bad initialize reply: ' + JSON.stringify(init), true, 68);
    shim.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
    const list = await call('tools/list', {});
    if (!(list.result && list.result.tools || []).some((tool) => tool.name === 'approve')) result('no approve tool: ' + JSON.stringify(list), true, 69);
    out({ type: 'assistant', message: { content: [{ type: 'text', text: 'Asking to write hello.txt' }] } });
    const target = path.join(process.cwd(), 'hello.txt');
    const answer = await call('tools/call', { name: 'approve', arguments: { tool_name: 'Write', input: { file_path: target, content: 'hi' }, tool_use_id: 'toolu_1' } });
    shim.stdin.end();
    const decision = JSON.parse(answer.result.content[0].text);
    finish(decision.behavior === 'allow', decision.message || 'denied');
  })().catch((error) => result(`MCP exchange failed: ${error.message}`, true, 71));
}
